package com.primehr.evidence.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.util.Locale;
@Entity @Table(name="evidence_indicator",uniqueConstraints={@UniqueConstraint(name="uk_evidence_indicator_code",columnNames={"agency_id","framework_version_id","normalized_code"}),@UniqueConstraint(name="uk_evidence_indicator_order",columnNames={"agency_id","pillar_id","display_order"})})
public class EvidenceIndicator extends RspAuditedEntity{@Column(name="framework_version_id",nullable=false,length=36)private String frameworkVersionId;@Column(name="pillar_id",nullable=false,length=36)private String pillarId;@Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Column(nullable=false,length=300)private String title;@Column(length=2000)private String description;@Column(name="evaluation_guidance",nullable=false,length=4000)private String evaluationGuidance;@Column(name="display_order",nullable=false)private int displayOrder;protected EvidenceIndicator(){}public EvidenceIndicator(String agency,String framework,String pillar,String code,String title,String description,String guidance,int order){super(agency);frameworkVersionId=requiredText(framework,"frameworkVersionId");pillarId=requiredText(pillar,"pillarId");this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);this.title=requiredText(title,"title");this.description=optionalText(description);evaluationGuidance=requiredText(guidance,"evaluationGuidance");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getPillarId(){return pillarId;}public String getCode(){return code;}public String getTitle(){return title;}public String getDescription(){return description;}public String getEvaluationGuidance(){return evaluationGuidance;}public int getDisplayOrder(){return displayOrder;}}
